ITEMS.append({
 "id": "l237-c1-mono-exinta-lepta", "title": "Γιατί η ώρα έχει εξήντα λεπτά; Μια κληρονομιά από τη Μεσοποταμία", "title_en": "Why does an hour have sixty minutes? A legacy from Mesopotamia", "type": "monologue", "level": "C1",
 "context_el": "Ακούτε ένα απόσπασμα από μια εκπομπή για την ιστορία των αριθμών.",
 "script": [
  L("Ομιλητής", "m", "Μετράμε με το δεκαδικό σύστημα, πιθανότατα επειδή έχουμε δέκα δάχτυλα. Κι όμως, όταν κοιτάμε το ρολόι, ξαφνικά μετράμε με εξηντάδες: εξήντα δευτερόλεπτα, εξήντα λεπτά. Το ίδιο κάνουμε και με τις μοίρες του κύκλου. Από πού προέρχεται αυτή η παραξενιά;", "We count in the decimal system, probably because we have ten fingers. And yet when we look at the clock, we suddenly count in sixties: sixty seconds, sixty minutes. We do the same with the degrees of a circle. Where does this oddity come from?"),
  L("Ομιλητής", "m", "Η απάντηση βρίσκεται στην αρχαία Μεσοποταμία. Οι Σουμέριοι και αργότερα οι Βαβυλώνιοι χρησιμοποιούσαν ένα σύστημα με βάση το εξήντα. Γιατί το εξήντα; Μια πιθανή εξήγηση είναι ότι διαιρείται με πάρα πολλούς αριθμούς: με το δύο, το τρία, το τέσσερα, το πέντε, το έξι, το δέκα, το δώδεκα. Για εμπόρους που μοίραζαν σιτάρι ή γη, αυτό ήταν τεράστιο πλεονέκτημα.", "The answer lies in ancient Mesopotamia. The Sumerians and later the Babylonians used a system based on sixty. Why sixty? One possible explanation is that it divides by a great many numbers: by two, three, four, five, six, ten, twelve. For merchants dividing up grain or land, that was a huge advantage."),
  L("Ομιλητής", "m", "Οι Βαβυλώνιοι ήταν επίσης εξαιρετικοί αστρονόμοι, και οι πίνακές τους με τις θέσεις των άστρων γράφονταν με αυτό το σύστημα. Όταν οι Έλληνες αστρονόμοι, όπως ο Ίππαρχος και αργότερα ο Πτολεμαίος, παρέλαβαν αυτή τη γνώση, κράτησαν τις εξηντάδες για τις γωνίες και τους υπολογισμούς τους, παρόλο που για όλα τα άλλα χρησιμοποιούσαν δεκαδικούς αριθμούς.", "The Babylonians were also excellent astronomers, and their tables of star positions were written in this system. When Greek astronomers such as Hipparchus and later Ptolemy took over this knowledge, they kept the sixties for their angles and calculations, even though for everything else they used decimal numbers."),
  L("Ομιλητής", "m", "Από την αστρονομία, οι εξηντάδες πέρασαν στη μέτρηση του χρόνου. Η Γαλλική Επανάσταση προσπάθησε να καθιερώσει δεκαδική ώρα, με δέκα ώρες την ημέρα και εκατό λεπτά την ώρα. Το πείραμα εγκαταλείφθηκε μέσα σε λίγα χρόνια. Οι συνήθειες, όπως φαίνεται, είναι πιο ανθεκτικές από τις επαναστάσεις, και έτσι κάθε φορά που κοιτάμε το ρολόι μας, κάνουμε, χωρίς να το ξέρουμε, μαθηματικά της Βαβυλώνας.", "From astronomy, the sixties passed into the measurement of time. The French Revolution tried to introduce decimal time, with ten hours a day and a hundred minutes an hour. The experiment was abandoned within a few years. Habits, it seems, are tougher than revolutions, and so every time we look at our watch we are, without knowing it, doing Babylonian mathematics."),
 ],
 "questions": [
  Q("Ποια πιθανή εξήγηση δίνεται για την επιλογή του εξήντα;", ["Ότι ήταν ο αριθμός των θεών", "Ότι διαιρείται με πάρα πολλούς αριθμούς", "Ότι αντιστοιχούσε στις μέρες του μήνα", "Ότι ήταν εύκολο να γραφτεί"], 1, "διαιρείται με πάρα πολλούς αριθμούς"),
  Q("Γιατί ήταν το σύστημα αυτό πλεονέκτημα για τους εμπόρους;", ["Γιατί έκανε πιο εύκολο το μοίρασμα σιταριού ή γης", "Γιατί μείωνε τους φόρους", "Γιατί ήταν μυστικό", "Γιατί το χρησιμοποιούσαν όλοι οι λαοί"], 0, "Για εμπόρους που μοίραζαν σιτάρι ή γη, αυτό ήταν τεράστιο πλεονέκτημα"),
  Q("Τι έκαναν οι Έλληνες αστρονόμοι με τις εξηντάδες;", ["Τις απέρριψαν", "Τις κράτησαν για τις γωνίες και τους υπολογισμούς τους", "Τις χρησιμοποίησαν για όλα", "Τις αντικατέστησαν με δωδεκάδες"], 1, "κράτησαν τις εξηντάδες για τις γωνίες και τους υπολογισμούς τους"),
  Q("Τι έγινε με τη δεκαδική ώρα της Γαλλικής Επανάστασης;", ["Ισχύει ακόμη στη Γαλλία", "Εγκαταλείφθηκε μέσα σε λίγα χρόνια", "Υιοθετήθηκε από τους αστρονόμους", "Δεν εφαρμόστηκε ποτέ"], 1, "Το πείραμα εγκαταλείφθηκε μέσα σε λίγα χρόνια"),
 ],
 "gloss": {"δεκαδικό": "δεκαδικός — decimal", "εξηντάδες": "εξηντάδα — group of sixty", "μοίρες": "μοίρα — degree", "παραξενιά": "παραξενιά — oddity, quirk", "Σουμέριοι": "Σουμέριος — Sumerian", "Βαβυλώνιοι": "Βαβυλώνιος — Babylonian", "διαιρείται": "διαιρούμαι — to be divisible", "πλεονέκτημα": "πλεονέκτημα — advantage", "παρέλαβαν": "παραλαμβάνω — to take over, receive", "γωνίες": "γωνία — angle", "καθιερώσει": "καθιερώνω — to establish", "ανθεκτικές": "ανθεκτικός — durable, resilient"},
})
ITEMS.append({
 "id": "l237-c1-int-kril", "title": "Μια θαλάσσια βιολόγος για το κριλ της Ανταρκτικής", "title_en": "A marine biologist on Antarctic krill", "type": "interview", "level": "C1",
 "context_el": "Μια Ελληνίδα θαλάσσια βιολόγος, που έχει πάρει μέρος σε ερευνητικές αποστολές στην Ανταρκτική, μιλά σε μια ραδιοφωνική εκπομπή επιστήμης.",
 "script": [
  L("Δημοσιογράφος", "m", "Μελετάτε ένα ζώο που οι περισσότεροι ακροατές μας δεν έχουν ακούσει ποτέ: το κριλ. Τι είναι;", "You study an animal that most of our listeners have never heard of: krill. What is it?"),
  L("Βιολόγος", "f", "Είναι ένα μικρό καρκινοειδές, που μοιάζει με γαριδάκι και έχει μήκος περίπου πέντε εκατοστά. Μόνο του δεν είναι εντυπωσιακό. Όμως ζει σε τεράστια σμήνη, που μερικές φορές βάφουν τη θάλασσα κόκκινη. Υπολογίζεται ότι το συνολικό βάρος του κριλ της Ανταρκτικής είναι από τα μεγαλύτερα που έχει οποιοδήποτε ζωικό είδος στον πλανήτη.", "It's a small crustacean that looks like a tiny shrimp and is about five centimetres long. On its own it isn't impressive. But it lives in huge swarms that sometimes turn the sea red. The total weight of Antarctic krill is estimated to be among the largest of any animal species on the planet."),
  L("Δημοσιογράφος", "m", "Γιατί είναι τόσο σημαντικό;", "Why is it so important?"),
  L("Βιολόγος", "f", "Γιατί από αυτό εξαρτώνται σχεδόν όλα τα μεγάλα ζώα της περιοχής: οι φάλαινες, οι φώκιες, οι πιγκουίνοι, πολλά ψάρια και πουλιά. Αν αφαιρέσετε το κριλ, η τροφική αλυσίδα της Ανταρκτικής καταρρέει. Και το κριλ, με τη σειρά του, τρέφεται με μικροσκοπικά φύκια που αναπτύσσονται κάτω από τον πάγο της θάλασσας, ειδικά τον χειμώνα.", "Because almost all the large animals of the region depend on it: whales, seals, penguins, many fish and birds. Take away the krill, and the Antarctic food chain collapses. And krill, in turn, feeds on microscopic algae that grow under the sea ice, especially in winter."),
  L("Δημοσιογράφος", "m", "Άρα η κλιματική αλλαγή το απειλεί;", "So climate change threatens it?"),
  L("Βιολόγος", "f", "Είναι ένας από τους κινδύνους που μελετάμε. Σε ορισμένες περιοχές ο θαλάσσιος πάγος λιγοστεύει, και μαζί του η τροφή των νεαρών κριλ. Υπάρχει και η αλιεία: το κριλ ψαρεύεται για να γίνει τροφή στις ιχθυοκαλλιέργειες ή συμπληρώματα διατροφής. Οι ποσότητες ελέγχονται από μια διεθνή επιτροπή, αλλά πολλοί επιστήμονες ζητούν πιο αυστηρά όρια. Αυτό που προσπαθώ να εξηγώ είναι ότι, για να προστατέψεις τη φάλαινα, πρέπει πρώτα να προστατέψεις αυτό το μικρό γαριδάκι.", "It's one of the risks we study. In some areas the sea ice is shrinking, and with it the food of young krill. There's also fishing: krill is caught to become feed for fish farms or food supplements. The quantities are controlled by an international commission, but many scientists are calling for stricter limits. What I try to explain is that to protect the whale, you first have to protect this little shrimp."),
 ],
 "questions": [
  Q("Τι λέει η βιολόγος για το συνολικό βάρος του κριλ;", ["Ότι είναι πολύ μικρό", "Ότι είναι από τα μεγαλύτερα κάθε ζωικού είδους στον πλανήτη", "Ότι κανείς δεν μπορεί να το υπολογίσει", "Ότι μειώθηκε στο μισό"], 1, "το συνολικό βάρος του κριλ της Ανταρκτικής είναι από τα μεγαλύτερα"),
  Q("Γιατί είναι τόσο σημαντικό το κριλ;", ["Γιατί καθαρίζει το νερό", "Γιατί από αυτό εξαρτώνται σχεδόν όλα τα μεγάλα ζώα της περιοχής", "Γιατί λιώνει τον πάγο", "Γιατί είναι νόστιμο"], 1, "από αυτό εξαρτώνται σχεδόν όλα τα μεγάλα ζώα της περιοχής"),
  Q("Πώς επηρεάζει η μείωση του πάγου το κριλ;", ["Του αφήνει περισσότερο χώρο", "Μειώνει την τροφή των νεαρών κριλ", "Το κάνει πιο εύκολο θήραμα για τις φάλαινες", "Δεν το επηρεάζει"], 1, "ο θαλάσσιος πάγος λιγοστεύει, και μαζί του η τροφή των νεαρών κριλ"),
  Q("Τι ζητούν πολλοί επιστήμονες;", ["Να απαγορευτεί κάθε έρευνα", "Πιο αυστηρά όρια στην αλιεία του κριλ", "Να εκτρέφεται κριλ σε φάρμες", "Να μεταφερθούν φάλαινες σε άλλες θάλασσες"], 1, "πολλοί επιστήμονες ζητούν πιο αυστηρά όρια"),
 ],
 "gloss": {"αποστολές": "αποστολή — expedition, mission", "καρκινοειδές": "καρκινοειδές — crustacean", "γαριδάκι": "γαριδάκι — tiny shrimp", "σμήνη": "σμήνος — swarm", "εξαρτώνται": "εξαρτώμαι — to depend", "τροφική αλυσίδα": "τροφική αλυσίδα — food chain", "καταρρέει": "καταρρέω — to collapse", "φύκια": "φύκι — alga, seaweed", "λιγοστεύει": "λιγοστεύω — to diminish, shrink", "αλιεία": "αλιεία — fishing, fishery", "ιχθυοκαλλιέργειες": "ιχθυοκαλλιέργεια — fish farm", "συμπληρώματα διατροφής": "συμπλήρωμα διατροφής — food supplement"},
})
